// Set Config — row-and-binary-carrying passthrough.
// BUG 21: the Set node this replaces dropped the webhook's binary CSV on the floor.
// D-16b: this row's `allow_create` is NOT the Cloud create gate any more — it does not
// survive Extract From File's fresh-item parse, and the real gate now lives at Decide
// Action, which reads the baked ALLOW_HUBSPOT_CREATE constant instead. This seed stays
// here only for the LOCAL/dry-run echo lane (DECIDE_LOCAL), which legitimately keeps
// reading a row-seeded gate.
// D-70-05/D-70-07 (Phase 70 Plan 02): normalizes the caller's own client-minted
// `run_id` (a multipart form FIELD, so n8n parses it into `$json.body.run_id` — the
// same `filename=None` idiom `source_by_field` already proves) and echoes it as this
// node's OWN output field. This is the ingest lane's echo node: `watch.
// _execution_carries_run_id` correlates a settled execution by finding THIS node's
// output carrying the requested `run_id`, exactly the mechanism the enrichment lane's
// "Parse HubSpot Event" already provides there. A request that carries no `run_id`
// echoes `null` — this lane keeps working for a caller that predates the change.
return $input.all().map((it) => {
  const body = it.json.body || {};
  return {
    json: { ...it.json, allow_create: false, run_id: body.run_id ?? it.json.run_id ?? null },
    binary: it.binary,
  };
});

// Build Ingest Ack — D-70-07: the lane's ONLY responder.
const item = ($input.first() && $input.first().json) || {};
return [{ json: { run_id: item.run_id ?? null, accepted: true, row_ids: [] } }];

// Set Config Fields — parses the round-level source map once, for the "combineAll"
// broadcast merge to fan onto every row.
function _sourceByFieldFromEnvelope(cfg) {
  const body = (cfg && (cfg.body ?? cfg)) || {};
  let map = (body && typeof body === 'object') ? body.source_by_field : null;
  if (typeof map === 'string') {
    try { map = JSON.parse(map); } catch (e) { map = null; }
  }
  return (map && typeof map === 'object' && !Array.isArray(map)) ? map : {};
}
const cfg = ($input.first() && $input.first().json) || {};
return [{ json: { source_by_field: _sourceByFieldFromEnvelope(cfg) } }];

// columnMap.js — pure-JS header remap for n8n Code nodes.
//
// Mirrors src/column_mapper.py + config/column_mapping.yaml: arbitrary source
// headers -> canonical HubSpot contact props via case-insensitive / whitespace-
// collapsed aliases; unmapped columns are dropped. requiredIdentity mirrors the
// column_mapping required_identity reject rule (email OR firstname+lastname+company OR
// linkedin_url).

// Embedded alias table (source of truth: config/column_mapping.yaml). Keys are
// already lowercased/whitespace-collapsed, matching _normHeader.
const ALIASES = {
  // email
  "email": "email",
  "email address": "email",
  "e-mail": "email",
  "e-mail address": "email",
  // firstname
  "firstname": "firstname",
  "first name": "firstname",
  "fname": "firstname",
  "given name": "firstname",
  // lastname
  "lastname": "lastname",
  "last name": "lastname",
  "surname": "lastname",
  // jobtitle
  "jobtitle": "jobtitle",
  "job title": "jobtitle",
  "title": "jobtitle",
  "position": "jobtitle",
  // linkedin_url
  "linkedin_url": "linkedin_url",
  "linkedin": "linkedin_url",
  "linkedin url": "linkedin_url",
  "li": "linkedin_url",
  "linkedin profile": "linkedin_url",
  // phone
  "phone": "phone",
  "mobile": "phone",
  "tel": "phone",
  // company
  "company": "company",
  "organization": "company",
  "organisation": "company",
  "account": "company",
  "org.": "company",
  // company_id — manual contact->company association override (2026-08-25). Rides the
  // row for Build Company Link; never written as a HubSpot contact property.
  "company_id": "company_id",
  "company id": "company_id",
  "hubspot company id": "company_id",
  "associated company id": "company_id",
  "associatedcompanyid": "company_id",
};

function _normHeader(header) {
  // Trim, collapse internal whitespace, lowercase — matches column_mapper._norm_header.
  return String(header).split(/\s+/).filter(Boolean).join(" ").toLowerCase();
}

// mapRow(rawRow, mapping?) — mapping optional; defaults to embedded ALIASES.
// Accepts either a full column_mapping object ({aliases:{...}}) or a bare alias map.
function mapRow(rawRow, mapping) {
  let aliases = ALIASES;
  if (mapping) aliases = mapping.aliases || mapping;
  const out = {};
  for (const key of Object.keys(rawRow || {})) {
    if (typeof key !== "string") continue; // malformed header -> skip, never throw
    const canonical = aliases[_normHeader(key)];
    if (canonical) out[canonical] = rawRow[key];
  }
  return out;
}

function _present(v) {
  return v !== null && v !== undefined && String(v).trim() !== "";
}

// requiredIdentity(row) — email OR (firstname AND lastname AND company) OR linkedin_url.
// Mirrors config/column_mapping.yaml's required_identity.any_of (3 groups).
function requiredIdentity(row) {
  if (!row) return false;
  if (_present(row.email)) return true;
  if (_present(row.firstname) && _present(row.lastname) && _present(row.company)) return true;
  return _present(row.linkedin_url);
}

// --- n8n wrapper: map arbitrary upload headers -> canonical props ---
const rows = $input.all();
const out = [];
for (const it of rows) {
  const raw = it.json;
  const mapped = mapRow(raw);
  const ok = requiredIdentity(mapped);
  out.push({ json: {
    ...mapped,
    allow_create: raw.allow_create === true,
    // Phase 70 Plan 02 (D-70-04): mapRow() drops every key outside its own alias
    // table, same reason `allow_create` above is re-added explicitly — `source_by_field`
    // (broadcast onto every row by the "combineAll" merge between "Extract From File"
    // and this node) would otherwise be lost here, before "Merge Contacts" ever reads it.
    source_by_field: raw.source_by_field || {},
    reject: !ok,
    ...(ok ? {} : {
      outcome: "rejected",
      reject_reason: "missing required identity (need email OR firstname+lastname+company)"
    })
  }});
}
return out;

// normalizePhone.js — pure-JS AU phone normalizer for n8n Code nodes.
//
// DISCLAIMER: This is an AU-ONLY heuristic, NOT libphonenumber. It cannot import
// npm (n8n Code nodes run pure JS with no requires), so it recognises only the AU
// formats the ingestion pipeline actually sees. Any number that is non-AU or
// ambiguous returns null — the caller must route null to review, never silently
// drop or guess. A leading '+' is trusted as already-E.164 and passed through
// (separators stripped) WITHOUT a validity check, so an invalid '+...' string is
// kept as-is here where the Python oracle (phonenumbers.is_valid_number) would
// reject it. Swap this for a phone-validation API for global fidelity later.
//
// Mirrors src/normalizer.py normalize_phone for the AU cases the parity test pins.

function normalizePhoneAU(raw) {
  if (raw === null || raw === undefined || raw === "") return null;
  // Strip spaces, dashes, parens, dots — everything that is pure separator.
  const s = String(raw).replace(/[\s\-().]/g, "");
  if (s === "") return null;

  // Already international: trust the '+', keep the digits after it.
  if (s.startsWith("+")) {
    const digits = s.slice(1);
    if (!/^\d+$/.test(digits)) return null; // "+garbage" -> review
    return "+" + digits;
  }

  if (!/^\d+$/.test(s)) return null; // any non-digit leftover -> not AU/ambiguous

  // 0XXXXXXXXX — 10-digit AU national (mobile 04.. or landline 0[2378]..).
  if (s.length === 10 && s[0] === "0") {
    return "+61" + s.slice(1);
  }

  // 61XXXXXXXXX — AU country code without the '+'.
  if (s.length === 11 && s.startsWith("61")) {
    return "+" + s;
  }

  return null; // anything else is non-AU or ambiguous -> review
}

// normalizePhone(raw, region) — region-aware E.164 normalizer.
//
// Still NOT libphonenumber (n8n Code nodes can't require npm), but deterministic and
// keyed off the ISO2 country the PROVIDERS already return (Lusha location.country_iso2,
// Apollo person country, etc.) instead of guessing. Rules, in order:
//   1. Already `+E.164` -> trust and keep (digits 6-15).
//   2. Known region -> prepend that country's calling code (stripping a trunk 0 for
//      AU/NZ/GB/IE, a leading 1 for US/CA), gated by a per-country NSN-length sanity check.
//   3. Unknown/absent region -> fall back to normalizePhoneAU (AU heuristic). A non-AU
//      national number then returns null -> the caller drops it (never a bad write).
// The NSN-length gate is a sanity filter, not full validation; swap for a phone API when
// global precision matters (same external-call pattern as the email verifier).
const CALLING_CODE = { AU: "61", NZ: "64", US: "1", CA: "1", GB: "44", IE: "353", IN: "91", SG: "65" };
const NSN_LEN = { "61": [9], "64": [8, 9], "1": [10], "44": [9, 10], "353": [9], "91": [10], "65": [8] };
const TRUNK_REGIONS = /^(AU|NZ|GB|IE)$/;

function _nsnOk(cc, nsn) {
  const lens = NSN_LEN[cc];
  return lens ? lens.includes(nsn.length) : (nsn.length >= 6 && nsn.length <= 14);
}

function normalizePhone(raw, region) {
  if (raw === null || raw === undefined || raw === "") return null;
  const s = String(raw).replace(/[\s\-().]/g, "");
  if (s === "") return null;
  if (s.startsWith("+")) {
    const d = s.slice(1);
    return /^\d{6,15}$/.test(d) ? "+" + d : null;
  }
  if (!/^\d+$/.test(s)) return null;
  const r = String(region || "").toUpperCase();
  const cc = CALLING_CODE[r];
  if (!cc) return normalizePhoneAU(s); // unknown region -> AU heuristic (non-AU -> null)
  if (s.startsWith(cc) && _nsnOk(cc, s.slice(cc.length))) return "+" + s; // already has CC
  let nsn = s;
  if (TRUNK_REGIONS.test(r) && nsn.startsWith("0")) nsn = nsn.slice(1);          // trunk 0
  if (cc === "1" && nsn.length === 11 && nsn.startsWith("1")) nsn = nsn.slice(1); // US/CA leading 1
  return _nsnOk(cc, nsn) ? "+" + cc + nsn : null;
}

// --- n8n wrapper: AU-heuristic phone -> E.164 (null => review) ---
return $input.all().map((it) => {
  const row = it.json;
  return { json: { ...row, phone_normalized: normalizePhoneAU(row.phone) } };
});

// normalizeEmail.js — pure-JS email normalization for n8n Code nodes.
//
// normalizeEmailBasic does a BASIC syntactic check + trim/lowercase only. The
// authoritative validation is the external rapid-email-verifier API downstream;
// applyEmailVerification maps that verifier's response onto the row. This mirrors
// src/normalizer.py normalize_email closely enough for identity/dedupe parity:
// obviously-malformed -> null, otherwise trimmed+lowercased.

function normalizeEmailBasic(raw) {
  if (raw === null || raw === undefined) return null;
  const s = String(raw).trim().toLowerCase();
  if (s === "") return null;
  // Basic shape: local@domain.tld, no spaces, one @, a dotted domain.
  // Deliberately conservative — the verifier API is the real authority.
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s)) return null;
  return s;
}

// Map a rapid-email-verifier result onto the row. `verifierResult` shape:
//   { status: "VALID"|"PROBABLY_VALID"|"INVALID_FORMAT"|"INVALID_DOMAIN"|"DISPOSABLE",
//     aliasOf?: "canonical@example.com" }
// Returns the fields to merge onto the row.
function applyEmailVerification(row, verifierResult) {
  const status = (verifierResult && verifierResult.status) || "INVALID_FORMAT";
  const alias = verifierResult && verifierResult.aliasOf;
  const raw = row ? row.email : undefined;

  // aliasOf is the canonical address when the verifier resolved one.
  const canonical = alias
    ? normalizeEmailBasic(alias)
    : normalizeEmailBasic(raw);

  const valid = status === "VALID" || status === "PROBABLY_VALID";

  return {
    email_normalized: valid ? canonical : normalizeEmailBasic(raw),
    email_valid: valid,
    email_status: status,
    needs_review_reason: valid ? null : `email verifier: ${status}`,
  };
}

// --- n8n wrapper: collapse rows -> ONE item {emails:[...]} for the batch API ---
// Phase 70 Plan 02 (D-70-04): `_rows` carries the N pre-collapse rows THROUGH the
// batch call as a NESTED field on this same one-item output — "Verify Emails (batch)"'s
// own jsonBody sends only `$json.emails` (HTTP_VERIFY), so `_rows` never reaches the
// external API. The carry-merge spliced after that HTTP node re-attaches this item
// (still 1-item, matching the HTTP response's own 1-item count) so "Apply Email" reads
// both the verifier's `results` and its own N rows back via $input, never by name.
const rows = $input.all();
const emails = [];
const seen = new Set();
for (const it of rows) {
  const e = normalizeEmailBasic(it.json.email);
  if (e && !seen.has(e)) { seen.add(e); emails.push(e); }
}
return [{ json: { emails, _rows: rows.map((it) => it.json) } }];

// normalizeEmail.js — pure-JS email normalization for n8n Code nodes.
//
// normalizeEmailBasic does a BASIC syntactic check + trim/lowercase only. The
// authoritative validation is the external rapid-email-verifier API downstream;
// applyEmailVerification maps that verifier's response onto the row. This mirrors
// src/normalizer.py normalize_email closely enough for identity/dedupe parity:
// obviously-malformed -> null, otherwise trimmed+lowercased.

function normalizeEmailBasic(raw) {
  if (raw === null || raw === undefined) return null;
