// Reads ONLY the canonical `write_request` shape (D-70-12). A row with no
// write_request is refused, not rescued by any fallback. Empty allowlist denies all.
// D-70-14: maps every item to a verdict — never filters. Output count == input count.
return $input.all().map((it) => {
  var wr = it.json.write_request;
  var allowed = !!wr && _writeSafetyAllows('create', wr.hs_object_id || null, wr.domain || null);
  if (allowed) return { json: { ...it.json, write_allowed: true } };
